/** Shared by the inline loader and its module-only fallback; no generated byte table is imported. */
import type { DeclaredBootTotals } from './asset-totals';
import { loadRiderOutfit } from '../ui/outfit';

export function selectedBootTotals(totals: DeclaredBootTotals, search: string): { heroModels: number; bootArt: number } {
  const outfit = loadRiderOutfit(new URLSearchParams(search).get('outfit'));
  return { heroModels: totals.heroModels[outfit], bootArt: totals.bootArt };
}
